package github

import (
	"crypto/sha256"
	"fmt"
	api "renovate-operator/api/v1alpha1"
	"renovate-operator/internal/utils"
)

func GetNameForGithubAppSecret(job *api.RenovateJob) string {
	return GetNameForGithubAppSecretFromJobName(job.Name)
}
func GetNameForGithubAppSecretFromJobName(name string) string {
	return githubAppSecretName(name, "github-app")
}

// GetNameForGithubAppCredentialsSecret names the generated Secret holding the
// App credentials of a RenovateJob generated by a GitHubAppInstallationSet.
func GetNameForGithubAppCredentialsSecret(jobName string) string {
	return githubAppSecretName(jobName, "github-app-credentials")
}

func githubAppSecretName(jobName, suffix string) string {
	name := utils.KubernetesCompatibleName(jobName)
	hash := sha256.Sum256([]byte(name))
	hashStr := fmt.Sprintf("%x", hash[:4])

	if len(name) > 43 {
		name = name[:43]
	}

	return fmt.Sprintf("%s-%s-%s", name, suffix, hashStr)
}
